#include <stdint.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

#define SYSCNFG_BASE_ADDR 0x40013800UL
#define SYSCFG_EXTICR1_OFFSET 0x08UL

#define RCC_BASE_ADDR 0x40023800UL
#define RCC_AHB1ENR_OFFSET 0x30UL

#define GPIOA_BASE_ADDR 0x40020000UL
#define GPIOA_MODE_REG_OFFSET 0x00UL

#define EXTI_REG_BASE_ADDR 0x40013C00UL
#define EXTI_IMR_OFFSET 0x00UL
#define EXTI_PR_OFFSET 0x14UL

volatile uint32_t *pSyscfgExticr1Address = (volatile uint32_t *) (SYSCNFG_BASE_ADDR + SYSCFG_EXTICR1_OFFSET);
volatile uint32_t *pRccAhb1EnrAddress = (volatile uint32_t *) (RCC_BASE_ADDR + RCC_AHB1ENR_OFFSET);
volatile uint32_t *pGpioaModeRegAddress = (volatile uint32_t *) (GPIOA_BASE_ADDR + GPIOA_MODE_REG_OFFSET);
volatile uint32_t *pExtiImrRegAddress = (volatile uint32_t *) (EXTI_REG_BASE_ADDR + EXTI_IMR_OFFSET);
volatile uint32_t *pExtiPrRegAddress = (volatile uint32_t *) (EXTI_REG_BASE_ADDR + EXTI_PR_OFFSET);

int main(void)
{
	//clear [3:0] pins to configure EXTI1 to recieve interrupts from PA0
	*pSyscfgExticr1Address &= ~(0xF << 0);

	//set bit at 0 in EXTI IMR REG for MR0 (PA0) to 1 (not masked)
	*pExtiImrRegAddress |= (1 << 0);

	//set bit at 0 in EXTI PR REG for PR0 (PA0) to 1 (trigger requested)
	*pExtiPrRegAddress |= (1 << 0);

	//enable peripheral clock for AHB1 GPIOA
	*pRccAhb1EnrAddress |= (1 << 0);

	//clear [1:0] pins to configure PA0 port as input
	*pGpioaModeRegAddress &= ~(0x3 << 0);

    /* Loop forever */
	for(;;);
}

void EXTI0_IRQHandler(void)
{
	*pExtiPrRegAddress |= (1 << 0);
}
